# Physics, mechanics (10+2 CBSE): units and dimensions, kinematics, laws of
# motion, work, energy and power, rotation, gravitation, and properties of
# solids and fluids. Take g = 10 m/s² unless stated.
ITEMS = [
    # ---------- Practice Test 1 ----------
    S(1, 1, "Units and dimensions", "What is the dimensional formula of force?",
      [r"$[MLT^{-2}]$", r"$[ML^2T^{-2}]$", r"$[MLT^{-1}]$", r"$[ML^{-1}T^{-2}]$"],
      r"Force = mass x acceleration, so its dimensions are $[M][LT^{-2}] = [MLT^{-2}]$. $[ML^2T^{-2}]$ is energy, $[MLT^{-1}]$ is momentum and $[ML^{-1}T^{-2}]$ is pressure."),
    S(1, 1, "Kinematics", "A car starts from rest and accelerates uniformly to 20 m/s in 5 s. How far does it travel in this time?",
      ["50 m", "100 m", "25 m", "40 m"],
      "Acceleration = 20 / 5 = 4 m/s². Distance = ½ x 4 x 5² = 50 m (or average speed 10 m/s x 5 s). 100 m comes from multiplying the final speed by the time, as if the car had moved at 20 m/s throughout."),
    S(1, 2, "Projectile motion", "A ball is thrown with a speed of 30 m/s at 30° above the horizontal. What is its time of flight? (g = 10 m/s²)",
      ["3 s", "6 s", "1.5 s", "5.2 s"],
      "Time of flight T = 2u sin θ / g = 2 x 30 x 0.5 / 10 = 3 s. 6 s leaves out sin θ, 1.5 s is the time to the top only, and 5.2 s uses cos 30° instead of sin 30°."),
    S(1, 2, "Laws of motion", "A 2 kg block is pulled along a floor by a horizontal force of 10 N. The friction force on it is 4 N. What is its acceleration?",
      ["3 m/s²", "5 m/s²", "7 m/s²", "6 m/s²"],
      "Net force = 10 - 4 = 6 N, so a = F / m = 6 / 2 = 3 m/s². 5 m/s² ignores friction, 7 m/s² adds the friction instead of subtracting it, and 6 is the net force in newtons, not yet divided by the mass."),
    S(1, 1, "Laws of motion", "Why do the action and reaction forces of Newton's third law not cancel each other?",
      ["They act on two different bodies", "They act at different times", "One of them is always larger", "They act in the same direction"],
      "Action and reaction are equal and opposite but act on different bodies, so each affects the motion of its own body. Forces cancel only when they act on the same body."),
    S(1, 1, "Work, energy and power", "What is the kinetic energy of a 0.5 kg ball moving at 4 m/s?",
      ["4 J", "2 J", "1 J", "8 J"],
      "KE = ½mv² = ½ x 0.5 x 4² = 4 J. 2 J is the momentum value (mv), 1 J forgets to square the speed, and 8 J leaves out the ½."),
    S(1, 2, "Work, energy and power", "A motor lifts a load of 100 kg through a height of 6 m in 20 s at a steady speed. What is its power output? (g = 10 m/s²)",
      ["300 W", "30 W", "3000 W", "6000 W"],
      "Work = mgh = 100 x 10 x 6 = 6000 J. Power = work / time = 6000 / 20 = 300 W. 6000 is the work done, not the power."),
    S(1, 2, "Gravitation", "At what height above the Earth's surface does the acceleration due to gravity become one-fourth of its value at the surface? (R is the radius of the Earth.)",
      ["R", "R/2", "2R", "4R"],
      r"$g' = g R^2 / (R + h)^2$. For $g' = g/4$ we need $(R + h)^2 = 4R^2$, so $R + h = 2R$ and $h = R$."),
    S(1, 1, "Gravitation", "The escape velocity of a body from the Earth's surface does NOT depend on",
      ["the mass of the body", "the mass of the Earth", "the radius of the Earth", "the gravitational constant"],
      r"Escape velocity $v_e = \sqrt{2GM/R}$, where M and R are the Earth's mass and radius. The mass of the escaping body cancels out, so a stone and a satellite need the same escape speed."),
    S(1, 2, "Rotational motion", "What is the moment of inertia of a thin ring of mass M and radius R about an axis through its centre, perpendicular to its plane?",
      [r"$MR^2$", r"$\frac{1}{2}MR^2$", r"$\frac{2}{5}MR^2$", r"$\frac{2}{3}MR^2$"],
      r"Every bit of a thin ring is at the same distance R from the axis, so $I = MR^2$. $\frac{1}{2}MR^2$ is a uniform disc, $\frac{2}{5}MR^2$ a solid sphere and $\frac{2}{3}MR^2$ a hollow sphere."),

    # ---------- Practice Test 2 ----------
    S(2, 1, "Units and dimensions", "Which is the SI unit of impulse?",
      ["N s", "N m", "J/s", "N/s"],
      "Impulse = force x time, so its unit is the newton second (N s), the same as kg m/s for momentum. N m is the unit of work or torque and J/s is the watt."),
    S(2, 1, "Kinematics", "A stone dropped from the top of a tower reaches the ground in 4 s. What is the height of the tower? (g = 10 m/s²)",
      ["80 m", "40 m", "16 m", "20 m"],
      "h = ½gt² = ½ x 10 x 4² = 80 m. 20 m forgets to square the time, 40 is the speed on reaching the ground (gt = 40 m/s), and 16 is just t²."),
    S(2, 1, "Kinematics", "What does the area under a velocity-time graph give?",
      ["Displacement", "Acceleration", "Speed", "Force"],
      "Area under a velocity-time graph = velocity x time = displacement. The slope of the same graph gives acceleration."),
    S(2, 2, "Conservation of momentum", "A gun of mass 4 kg fires a bullet of mass 20 g with a speed of 400 m/s. What is the recoil speed of the gun?",
      ["2 m/s", "0.2 m/s", "20 m/s", "8 m/s"],
      "Momentum is conserved: 4 x V = 0.020 x 400 = 8, so V = 2 m/s. 0.2 m/s and 20 m/s come from slipping a power of ten when converting 20 g to kilograms, and 8 m/s is the bullet's momentum (8 kg m/s) not yet divided by the gun's mass."),
    S(2, 2, "Friction", "The coefficient of static friction between a block and a plane is 0.75. At what angle of inclination will the block just begin to slide?",
      ["37°", "53°", "45°", "60°"],
      "At the angle of repose, tan θ = μ = 0.75 = 3/4, so θ is about 37°. 53° is the angle whose tangent is 4/3, 45° has tan θ = 1, and 60° has tan θ = 1.73."),
    S(2, 2, "Circular motion", "A car of mass 1000 kg goes round a curve of radius 50 m at a speed of 10 m/s. What centripetal force is needed?",
      ["2000 N", "200 N", "2 N", "1000 N"],
      "F = mv²/r = 1000 x 10² / 50 = 2000 N. 200 N forgets to square the speed, 1000 N is just the mass, and 2 N is v²/r, the acceleration, with the mass left out."),
    S(2, 1, "Work, energy and power", "A spring of spring constant 200 N/m is stretched by 0.1 m. How much elastic potential energy does it store?",
      ["1 J", "2 J", "10 J", "20 J"],
      "U = ½kx² = ½ x 200 x 0.1² = 1 J. 2 J leaves out the ½, and 10 J and 20 J forget to square the extension."),
    S(2, 2, "Gravitation", "How is the escape speed from the Earth's surface related to the orbital speed of a satellite orbiting just above the surface?",
      [r"Escape speed = $\sqrt{2}$ x orbital speed", "Escape speed = 2 x orbital speed", "Escape speed = orbital speed", r"Escape speed = orbital speed / $\sqrt{2}$"],
      r"Orbital speed near the surface is $v_o = \sqrt{GM/R}$ and escape speed is $v_e = \sqrt{2GM/R}$, so $v_e = \sqrt{2}\,v_o$, about 11.2 km/s against 7.9 km/s."),
    S(2, 2, "Fluids", "Which principle best explains the upward lift on an aircraft wing?",
      ["Bernoulli's principle", "Pascal's law", "Archimedes' principle", "Hooke's law"],
      "Air moves faster over the curved upper surface of the wing than under it. By Bernoulli's principle, faster flow means lower pressure, so the higher pressure below pushes the wing up."),
    S(2, 1, "Elasticity", "Within the elastic limit, the ratio of stress to strain is called the",
      ["modulus of elasticity", "coefficient of friction", "Poisson's ratio", "bulk strain"],
      "Hooke's law says stress is proportional to strain within the elastic limit; the constant ratio is the modulus of elasticity (Young's modulus for stretching). Poisson's ratio compares lateral and longitudinal strain."),

    # ---------- Drill only ----------
    S(0, 1, "Units and dimensions", "Which of these is a vector quantity?",
      ["Momentum", "Kinetic energy", "Power", "Work"],
      "Momentum (mass x velocity) has both size and direction, so it is a vector. Kinetic energy, power and work have size only."),
    S(0, 1, "Kinematics", "Two trains run on parallel tracks in opposite directions at 60 km/h and 40 km/h. What is the speed of one relative to the other?",
      ["100 km/h", "20 km/h", "50 km/h", "60 km/h"],
      "When bodies move in opposite directions their relative speed is the sum of their speeds: 60 + 40 = 100 km/h. 20 km/h would be correct only if they moved in the same direction."),
    S(0, 2, "Projectile motion", "A ball is thrown at 20 m/s at the angle that gives the maximum horizontal range. What is that range? (g = 10 m/s²)",
      ["40 m", "20 m", "34.6 m", "2 m"],
      "Maximum range is at 45°, where R = u² / g = 20² / 10 = 40 m. 20 m halves it, 34.6 m is the range at 30° or 60°, and 2 is u / g, the time in seconds to reach the top."),
    S(0, 2, "Laws of motion", "A person of mass 60 kg stands on a weighing scale in a lift that is accelerating upward at 2 m/s². What does the scale read? (g = 10 m/s²)",
      ["720 N", "600 N", "480 N", "120 N"],
      "Apparent weight R = m(g + a) = 60 x (10 + 2) = 720 N. 600 N is the weight at rest, 480 N is for a lift accelerating downward, and 120 N is only the extra force ma."),
    S(0, 1, "Circular motion", "A stone is whirled in a horizontal circle at constant speed on a string. How much work does the tension in the string do on it?",
      ["Zero", "Positive work every revolution", "Negative work every revolution", "Work equal to its kinetic energy"],
      "The tension points to the centre, at right angles to the velocity, so W = F d cos 90° = 0. That is why the speed stays constant."),
    S(0, 2, "Gravitation", "According to Kepler's third law, the square of a planet's period of revolution is proportional to",
      ["the cube of the semi-major axis of its orbit", "the square of its mass", "the semi-major axis of its orbit", "the cube of its speed"],
      r"Kepler's law of periods: $T^2 \propto a^3$, where a is the semi-major axis. A planet farther from the Sun takes much longer to go round."),
    S(0, 1, "Rotational motion", "A force of 20 N is applied at right angles to a spanner, 0.5 m from the nut. What is the torque on the nut?",
      ["10 N m", "40 N m", "20 N m", "5 N m"],
      "Torque = force x perpendicular distance = 20 x 0.5 = 10 N m. 40 N m divides by 0.5 instead of multiplying."),
    S(0, 2, "Fluids", "According to Stokes' law, the viscous drag on a small sphere of radius r moving slowly with speed v through a fluid of viscosity η is",
      [r"$6\pi\eta r v$", r"$6\pi\eta r^2 v$", r"$4\pi\eta r v^2$", r"$3\pi\eta r^2 v$"],
      r"Stokes' law: $F = 6\pi\eta r v$. The drag grows in direct proportion to both the radius and the speed, which is why a falling drop soon reaches a steady terminal velocity."),
]
